    "id": "revisao-menac-menac-completo-perda-autonoma",
    "law": "menac",
    "topic": "MENAC: organização, RH e competências",
    "subtopic": "Missão e atribuições",
    "familyId": "menac:revisao-menac-completo-perda-autonoma",
