    "id": "revisao-cga-cga-completo-referencia-reserva",
    "law": "cga",
    "topic": "CGA: inscrição, tempo e pensão",
    "subtopic": "(Passagem da reserva à reforma)",
    "familyId": "cga:revisao-cga-completo-referencia-reserva",
